nicho":"buffet_eventos","termos":["buffet de festas","espaço de eventos"]},{"nicho":"dedetizadora","termos":["dedetizadora"]},{"nicho":"grafica","termos":["gráfica"]},{"nicho":"odontologia_estetica","termos":["clínica odontológica","clínica de estética"]},{"nicho":"advocacia","termos":["escritório de advocacia"]},{"nicho":"estetica_harmonizacao","termos":["harmonização facial"]},{"nicho":"varejo_local","termos":["loja de roupas","loja de cosméticos"]}]};

