const proximas = PROXIMA > P.paginasMax ? [] : anteriores
  .filter((b) => b.token && b.sem_site >= P.minSemSiteParaProximaPagina)
  .sort((a, b) => b.sem_site - a.sem_site)
  .slice(0, orcamento);
