  ['fisioterapia', /\bfisioterap\w*/, /fisio|physiotherap/],
  ['ótica', /\boticas?\b/, /otica|oculos|optic/],
  ['autoescola', /\bauto ?escola\w*/, /auto ?escola|driving/],
