  const t = texto.replace(/(\d)\.(\d)/g, '$1,$2')
    .replace(new RegExp(`\\b(${NUM_EXTENSO_RE})(?:\\s+[uú]nicas?)?(?=\\s+(?:avalia|estrela))(?!\\s+avalia[çc][ãa]o[^.;!?]{0,40}?\\d,\\d)`, 'gi'), (_, w) => numExtenso(w))
