  ['estética', /\b(estetic\w*|harmoniza\w*)\b/, /estetic|beauty|harmoniz|spa|skin|laser|depila/],
  ['advocacia', /\b(advocacia|advogad\w*|juridic\w*)\b/, /advoc|advog|juridic|law|direito/],
